import pathlib,re,json,hashlib
source=pathlib.Path('content/m5/v1/canon/Blood_and_Thunder_Vaern_Eight_Nations_Canon_v1.0(3).md');text=source.read_text();digest=hashlib.sha256(source.read_bytes()).hexdigest();chunks=re.split(r'(?m)^# N',text)[1:];profiles=[]
titles={'N1':'Six Banners Championship','N2':'Twin Crown Classic','N3':'Commonwealth Cup','N4':'Iron Crown Championship','N5':'Sundaran League Prestige Championship','N6':'Grand Moot Championship','N7':'Republic Championship','N8':'Crown of Sands (Zaraveth)'}
capitals={'N2':'Highhall','N4':'Kharadun','N5':'Sundara','N8':'Zarathiel'}
for chunk in chunks:
 id='N'+chunk[0];name=chunk.split('\n')[0].split(' — ',1)[1]
 def section(number):
  m=re.search(r'(?ms)^## '+str(number)+r'\. [^\n]*\n\n(.*?)(?=^## |\Z)',chunk);return m.group(1).strip() if m else ''
 def first(number):return section(number).split('\n\n')[0].replace('**','')
 line=text[:text.index('# '+id+' — ')].count('\n')+1
 profiles.append({'id':id,'name':name,'prestigeName':titles[id],'capital':capitals.get(id,'Not unambiguously specified in canon'),'population':'Numerical population not specified in canon','government':first(4),'geography':first(2),'culture':first(3),'racing':first(10),'beasts':first(12),'mapAssetId':'world.map.'+id.lower()+'.v1','teamAssetId':'world.team.'+id.lower()+'.v1','sources':[{'path':str(source),'sha256':digest,'startLine':line,'endLine':line+len(chunk.splitlines())}]})
bindings={'N1':['Hearthvale Oval','Greywood Technical Circuit'],'N2':['Keldhaven Public Oval','Highhall Royal Circuit'],'N3':['Goldmeadow Festival Oval','Willowbridge Circuit'],'N4':['Kharadun Iron Crown Arena','Brassgate Technical Circuit'],'N5':['Valcera Harbor Circuit','Castriel Technical Circuit'],'N6':['Redstone Circuit','Redstone Circuit'],'N7':['Ironpass Circuit','Aurelith Proving Grounds'],'N8':['Sunstone Circuit','Singing Sands Trial']}
payload={'prestigeVenueNames':bindings,'version':1,'source':{'path':str(source),'sha256':digest},'profiles':profiles}
pathlib.Path('content/m6/world-profiles-v1.json').write_text(json.dumps(payload,indent=2,ensure_ascii=False)+'\n')
pathlib.Path('src/career/m6/world-content.generated.js').write_text('// Generated by scripts/m6/compile-world.py from unchanged canonical reference.\nexport const WORLD_CONTENT='+json.dumps(payload,ensure_ascii=False,separators=(',',':'))+';\n')
briefs=[]
for p in profiles:
 for kind in ['map','team']:
  briefs.append({'id':p[kind+'AssetId'],'status':'replaceable-placeholder','format':'SVG','viewBox':'0 0 512 320' if kind=='map' else '0 0 256 256','brief':('Non-geographic schematic nation card; no invented borders. ' if kind=='map' else 'Illustrative racing-team emblem, not a new playable team. ')+p['name']+'. Dark Deco Retro Cartoon, transparent geometric silhouettes; use canonical geography and racing culture. No baked text; SVG paths only, no external references or scripts.','sources':p['sources']})
pathlib.Path('content/m6/world-asset-briefs-v1.json').write_text(json.dumps({'version':1,'briefs':briefs},indent=2,ensure_ascii=False)+'\n')
